-- Session A
SELECT ListPrice FROM Production.Product WHERE ProductID = 680;

-- Session B, running at the same moment
SELECT ListPrice FROM Production.Product WHERE ProductID = 680;

-- Session A
BEGIN TRANSACTION;
UPDATE Production.Product SET ListPrice = 25.00 WHERE ProductID = 680;
UPDATE Production.Product SET ListPrice = 40.00 WHERE ProductID = 681;
-- transaction still open, not yet committed

-- Session B, while Session A's transaction above is still open
SELECT ListPrice FROM Production.Product WHERE ProductID = 680;

-- Session A, no explicit transaction
UPDATE Production.Product SET ListPrice = ListPrice + 1 WHERE ProductID = 680;

-- Session B, at nearly the same instant, no explicit transaction
UPDATE Production.Product SET ListPrice = ListPrice + 1 WHERE ProductID = 680;

-- Session A
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN TRANSACTION;
SELECT ListPrice FROM Production.Product WHERE ProductID = 680;
-- transaction left open

-- Session B, under the default isolation level, while Session A's transaction is still open
UPDATE Production.Product SET ListPrice = 59.99 WHERE ProductID = 680;

-- Database already has: ALTER DATABASE AdventureWorks2012 SET ALLOW_SNAPSHOT_ISOLATION ON;

-- Session A
SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
BEGIN TRANSACTION;
SELECT ListPrice FROM Production.Product WHERE ProductID = 680;
-- returns, say, 34.99 -- transaction left open

-- Session B, under ordinary READ COMMITTED, while Session A's transaction is still open
UPDATE Production.Product SET ListPrice = 49.99 WHERE ProductID = 680;
COMMIT;

-- Session A, continued, still inside its original open transaction
SELECT ListPrice FROM Production.Product WHERE ProductID = 680;

-- Session A
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN TRANSACTION;
SELECT COUNT(*) AS ProductCount FROM Production.Product WHERE ListPrice BETWEEN 500 AND 1000;
-- returns, say, 14 -- transaction left open

-- Session B, while Session A's transaction is still open
INSERT INTO Production.Product (Name, ProductNumber, ListPrice)
VALUES ('Road Bike, New', 'BK-NEW-01', 799.00);
-- commits immediately

-- Session A, continued
SELECT COUNT(*) AS ProductCount FROM Production.Product WHERE ListPrice BETWEEN 500 AND 1000;
